import {test,expect,type Page} from '@playwright/test'
const origin='http://127.0.0.1:4283'
async function openCatalog(page:Page,query=''){
 await page.goto(origin+'/?training-inbox-review=1'+query)
 await page.getByRole('button',{name:'More',exact:true}).click()
 await page.locator('[data-app-destination="coach"]').click()
 await page.locator('[data-app-destination="training"]').click()
 return page.getByRole('dialog',{name:'Level Up training',exact:true})
}
const trainingWrites=(page:Page)=>page.evaluate(()=>(window as unknown as {navigationFixture:{trainingWrites:number}}).navigationFixture.trainingWrites)
test.describe('Drill discovery',()=>{
 test('finds all tracked drills by setup and shows accurate player counts',async({page})=>{
  const training=await openCatalog(page)
  await training.getByRole('button',{name:'Round tracking',exact:true}).click()
  await expect(training.locator('[data-catalog-count]')).toHaveText('20 drills')
  for(const [name,count] of [['Solo',6],['With a partner',9],['Doubles group',5]] as const){
   await training.getByRole('button',{name,exact:true}).click()
   await expect(training.locator('[data-catalog-count]')).toHaveText(count+' drills')
   await expect(training.locator('[data-cards] [data-card]')).toHaveCount(count)
  }
  await expect(training.getByRole('button',{name:'Preview Middle Ball Rule',exact:true})).toHaveAccessibleDescription(/3 players.*Round tracking/)
  await expect(training.getByRole('button',{name:'Preview Serve Location Call',exact:true})).toHaveAccessibleDescription(/4 players.*Round tracking/)
  await training.getByRole('button',{name:'All setups',exact:true}).click()
  await expect(training.locator('[data-cards] [data-card]')).toHaveCount(20)
  expect(await trainingWrites(page)).toBe(0)
 })
 test('combines every filter, explains empty results and clears them together',async({page})=>{
  const training=await openCatalog(page)
  await training.getByRole('button',{name:'Round tracking',exact:true}).click()
  await training.getByRole('button',{name:'With a partner',exact:true}).click()
  await training.getByRole('searchbox',{name:'Find a drill',exact:true}).fill('Return Depth')
  await training.getByRole('combobox',{name:'Practice setting',exact:true}).selectOption('court')
  await training.getByRole('combobox',{name:'Time available',exact:true}).selectOption('10')
  await expect(training.locator('[data-catalog-count]')).toHaveText('1 drill')
  await training.getByRole('combobox',{name:'Time available',exact:true}).selectOption('5')
  await expect(training.getByRole('heading',{name:'No matching drills',exact:true})).toBeVisible()
  await expect(training.locator('[data-catalog-count]')).toHaveText('0 drills')
  await training.getByRole('button',{name:'Clear filters',exact:true}).click()
  await expect(training.locator('[data-catalog-count]')).toBeFocused()
  await expect(training.locator('[data-cards] [data-card]')).toHaveCount(24)
  await expect(training.getByRole('button',{name:'All setups',exact:true})).toHaveAttribute('aria-pressed','true')
  await expect(training.getByRole('button',{name:'Round tracking',exact:true})).toHaveAttribute('aria-pressed','false')
  await expect(training.getByRole('searchbox',{name:'Find a drill',exact:true})).toHaveValue('')
  await expect(training.getByRole('combobox',{name:'Practice setting',exact:true})).toHaveValue('')
  await expect(training.getByRole('combobox',{name:'Time available',exact:true})).toHaveValue('Infinity')
  await expect(training.getByRole('button',{name:'Clear filters',exact:true})).toBeHidden()
 })
 test('keeps keyboard focus and the search caret while filtering results',async({page})=>{
  const training=await openCatalog(page),solo=training.getByRole('button',{name:'Solo',exact:true}),search=training.getByRole('searchbox',{name:'Find a drill',exact:true})
  await solo.focus();await solo.press('Space')
  await expect(solo).toBeFocused();await expect(solo).toHaveAttribute('aria-pressed','true')
  await search.fill('Serve');await search.press('ArrowLeft');await search.press('x')
  await expect(search).toHaveValue('Servxe');await expect(search).toBeFocused()
  expect(await search.evaluate(el=>(el as HTMLInputElement).selectionStart)).toBe(5)
  await search.press('Backspace');await expect(search).toHaveValue('Serve')
  await expect(training.getByRole('button',{name:'Preview Serve Target Call',exact:true})).toBeVisible()
 })
 test('restores filters, expanded results and the exact card after a preview',async({page})=>{
  const training=await openCatalog(page)
  await training.getByRole('button',{name:'Solo',exact:true}).click()
  await training.getByRole('combobox',{name:'Time available',exact:true}).selectOption('15')
  await training.getByRole('button',{name:'Show more drills',exact:true}).click()
  const cards=training.locator('[data-cards] [data-card]'),card=cards.nth(30),id=await card.getAttribute('data-card')
  expect(await cards.count()).toBe(48);await card.click()
  await training.getByRole('button',{name:'Back to training cards',exact:true}).click()
  await expect(training.locator('[data-cards] [data-card]')).toHaveCount(48)
  await expect(training.locator('[data-card="'+id+'"]')).toBeFocused()
  await expect(training.getByRole('button',{name:'Solo',exact:true})).toHaveAttribute('aria-pressed','true')
  await expect(training.getByRole('combobox',{name:'Time available',exact:true})).toHaveValue('15')
 })
 test('ignores detached controls and clears filters when the account changes',async({page})=>{
  const training=await openCatalog(page)
  await training.getByRole('button',{name:'Round tracking',exact:true}).click()
  await training.getByRole('button',{name:'With a partner',exact:true}).click()
  await training.getByRole('searchbox',{name:'Find a drill',exact:true}).fill('Return Depth')
  await page.evaluate(()=>Object.assign(window,{oldDiscoveryControls:Array.from(document.querySelectorAll('[data-training-format],[data-catalog-tracked],[data-search],[data-catalog-clear]'))}))
  await training.getByRole('button',{name:'Preview Return Depth Lane',exact:true}).click()
  const fire=()=>page.evaluate(()=>{for(const el of (window as unknown as {oldDiscoveryControls:HTMLElement[]}).oldDiscoveryControls){el.click();el.dispatchEvent(new Event('input',{bubbles:true}))}})
  await fire();await expect(training.getByRole('heading',{name:'Return Depth Lane',exact:true})).toBeVisible()
  await training.getByRole('button',{name:'Back to training cards',exact:true}).click()
  await expect(training.locator('[data-catalog-count]')).toHaveText('1 drill')
  await expect(training.getByRole('searchbox',{name:'Find a drill',exact:true})).toHaveValue('Return Depth')
  await page.evaluate(()=>(window as unknown as {switchNavigationOwner:()=>void}).switchNavigationOwner())
  await expect(training).toHaveCount(0);await fire();await expect(training).toHaveCount(0)
  await page.evaluate(()=>(window as unknown as {switchNavigationOwner:(restore:boolean)=>void}).switchNavigationOwner(true))
  await page.getByRole('button',{name:'More',exact:true}).click()
  await page.locator('[data-app-destination="coach"]').click();await page.locator('[data-app-destination="training"]').click()
  await expect(training.getByRole('searchbox',{name:'Find a drill',exact:true})).toHaveValue('')
  await expect(training.getByRole('button',{name:'All setups',exact:true})).toHaveAttribute('aria-pressed','true')
  await expect(training.getByRole('button',{name:'Round tracking',exact:true})).toHaveAttribute('aria-pressed','false')
  expect(await trainingWrites(page)).toBe(0)
 })
 for(const width of [320,390])test('fits aligned setup controls and readable drill facts at '+width+'px',async({page},info)=>{
  await page.setViewportSize({width,height:844})
  const training=await openCatalog(page,width===320?'&large=1':'')
  await training.getByRole('button',{name:'Round tracking',exact:true}).click();await training.getByRole('button',{name:'Doubles group',exact:true}).click()
  const boxes=await training.locator('[data-training-format]').evaluateAll(els=>els.map(el=>{const r=el.getBoundingClientRect();return {width:r.width,height:r.height,x:r.x,y:r.y}}))
  expect(boxes).toHaveLength(4)
  for(const box of boxes){expect(box.width).toBeGreaterThanOrEqual(44);expect(box.height).toBeGreaterThanOrEqual(44)}
  expect(Math.abs(boxes[0].width-boxes[1].width)).toBeLessThanOrEqual(1)
  expect(boxes[0].y).toBe(boxes[1].y);expect(boxes[2].y).toBe(boxes[3].y)
  expect(await training.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true)
  await training.locator('.training-catalog-controls').scrollIntoViewIfNeeded();await page.screenshot({path:info.outputPath('drill-discovery-controls-'+width+'.png')})
  const card=training.getByRole('button',{name:'Preview Middle Ball Rule',exact:true})
  await card.scrollIntoViewIfNeeded();await expect(card).toHaveAccessibleDescription(/3 players.*Round tracking/)
  await page.screenshot({path:info.outputPath('drill-discovery-results-'+width+'.png')})
 })
 test('starts and privately saves a tracked drill from filtered results',async({page})=>{
  const training=await openCatalog(page)
  await training.getByRole('button',{name:'Round tracking',exact:true}).click();await training.getByRole('button',{name:'Doubles group',exact:true}).click()
  await training.getByRole('button',{name:'Preview Middle Ball Rule',exact:true}).click();await training.getByRole('button',{name:'Start training',exact:true}).click()
  await expect(training.getByRole('combobox',{name:'Training context',exact:true})).toHaveValue('doubles')
  await training.getByRole('spinbutton',{name:'Round 1',exact:true}).fill('0');await training.getByRole('spinbutton',{name:'Round 2',exact:true}).fill('8')
  await training.getByRole('combobox',{name:'Self-rated proof (0–5)',exact:true}).selectOption('2')
  await training.getByRole('button',{name:'Save completed session',exact:true}).click()
  await expect(training.locator('.training-history-latest')).toContainText('Middle Ball Rule')
  await expect(training.locator('.training-history-latest')).toContainText('R1 0/10; R2 8/10. Total 8/20.')
  expect(await trainingWrites(page)).toBe(1)
 })
})
